20	import Point from 'zrender/src/core/Point';
21	import type {
22	    MatrixCellLayoutInfo,
23	    MatrixDimensionCell,
24	    MatrixDimPair,
25	    MatrixXYLocator,
26	    MatrixXYLocatorRange,
27	} from './MatrixDim';
28	import type { NullUndefined } from '../../util/types';
29	import { eqNaN, isArray, isNumber } from 'zrender/src/core/util';
30	import { WH, XY } from '../../util/graphic';
31	import type { MatrixCoordRangeOption, MatrixCoordValueOption } from './MatrixModel';
32	import type { RectLike } from 'zrender/src/core/BoundingRect';
33	import { mathMax, mathMin } from '../../util/number';
34	
35	export const MatrixCellLayoutInfoType = {
36	    level: 1,
37	    leaf: 2,
38	    nonLeaf: 3,
39	} as const;
40	export type MatrixCellLayoutInfoType = (typeof MatrixCellLayoutInfoType)[keyof typeof MatrixCellLayoutInfoType];
41	
42	/**
43	 * @public Public to users in `chart.convertFromPixel`.
44	 */
45	export const MatrixClampOption = {
46	    // No clamp, be falsy, equals to null/undefined. It means if the input part is
47	    // null/undefined/NaN/outOfBoundary, the result part is NaN, rather than clamp to
48	    // the boundary of the matrix.
49	    none: 0,
50	    // Clamp, where null/undefined/NaN/outOfBoundary can be used to cover the entire row/column.
51	    all: 1,
52	    body: 2,
53	    corner: 3,
54	};
55	export type MatrixClampOption = (typeof MatrixClampOption)[keyof typeof MatrixClampOption];
56	
57	/**
58	 * For the x direction,
59	 *  - find dimension cell from `xMatrixDim`,
60	 *      - If `xDimCell` or `yDimCell` is not a leaf, return the non-leaf cell itself.
61	 *  - otherwise find level from `yMatrixDim`.
62	 *  - otherwise return `NullUndefined`.
63	 *
64	 * For the y direction, it's the opposite.
65	 */
66	export function coordDataToAllCellLevelLayout(
67	    coordValue: MatrixCoordValueOption,
68	    dims: MatrixDimPair,
69	    thisDimIdx: number // 0 | 1
70	): MatrixCellLayoutInfo | NullUndefined {
71	    // Find in body.
72	    let result: MatrixCellLayoutInfo | NullUndefined = dims[XY[thisDimIdx]].getCell(coordValue);
73	    // Find in corner or dimension area.
74	    if (!result && isNumber(coordValue) && coordValue < 0) {
75	        result = dims[XY[1 - thisDimIdx]].getUnitLayoutInfo(thisDimIdx, Math.round(coordValue));
76	    }
77	    return result;
78	}
79	
80	export function resetXYLocatorRange(out: unknown[] | NullUndefined): MatrixXYLocatorRange {
81	    const rg = (out || []) as MatrixXYLocatorRange;
82	    rg[0] = rg[0] || [];
83	    rg[1] = rg[1] || [];
84	    rg[0][0] = rg[0][1] = rg[1][0] = rg[1][1] = NaN;
85	    return rg;
86	}
87	
88	/**
89	 * If illegal or out of boundary, set NaN to `locOut`. (See `isLocatorRangeInvalidOnDim`)
90	 * x dimension and y dimension are calculated separately.
91	 */
92	export function parseCoordRangeOption(
93	    locOut: MatrixXYLocatorRange,
94	    // If illegal input or can not find any target, save reason to it.
95	    // Do nothing if `NullUndefined`.
96	    reasonOut: string[] | NullUndefined,
97	    data: MatrixCoordRangeOption[],
98	    dims: MatrixDimPair,
99	    clamp: MatrixClampOption,
100	): void {
101	    // x and y are supported to be handled separately - if one dimension is invalid
102	    // (may be users do not need that), the other one should also be calculated.
103	    parseCoordRangeOptionOnOneDim(locOut[0], reasonOut, clamp, data, dims, 0);
104	    parseCoordRangeOptionOnOneDim(locOut[1], reasonOut, clamp, data, dims, 1);
105	}
106	
107	function parseCoordRangeOptionOnOneDim(
108	    locDimOut: MatrixXYLocatorRange[number],
109	    reasonOut: string[] | NullUndefined,
110	    clamp: MatrixClampOption,
111	    data: MatrixCoordRangeOption[],
112	    dims: MatrixDimPair,
113	    dimIdx: number,
114	): void {
115	    locDimOut[0] = Infinity;
116	    locDimOut[1] = -Infinity;
117	
118	    const dataOnDim = data[dimIdx];
119	    const coordValArr = isArray(dataOnDim) ? dataOnDim : [dataOnDim];
120	    const len = coordValArr.length;
121	    const hasClamp = !!clamp;
122	
123	    if (len === 1 || len === 2) {
124	        parseCoordRangeOptionOnOneDimOnePart(locDimOut, reasonOut, coordValArr, hasClamp, dims, dimIdx, 0);
125	        if (len > 1) {
126	            parseCoordRangeOptionOnOneDimOnePart(locDimOut, reasonOut, coordValArr, hasClamp, dims, dimIdx, 1);
127	        }
128	    }
129	    else {
130	        if (reasonOut) {
131	            reasonOut.push(`Can only contain 1 or 2 coords, rather than ${len}.`);
132	        }
133	        locDimOut[0] = locDimOut[1] = NaN;
134	    }
135	
136	    if (hasClamp) {
137	        // null/undefined/NaN or illegal data represents the entire row/column;
138	        // Cover the entire locator regardless of body or corner, and confine it later.
139	        let locLowerBound = -dims[XY[1 - dimIdx]].getLocatorCount(dimIdx);
140	        let locUpperBound = dims[XY[dimIdx]].getLocatorCount(dimIdx) - 1;
141	
142	        if (clamp === MatrixClampOption.body) {
143	            locLowerBound = mathMax(0, locLowerBound);
144	        }
145	        else if (clamp === MatrixClampOption.corner) {
146	            locUpperBound = mathMin(-1, locUpperBound);
147	        }
148	
149	        if (locUpperBound < locLowerBound) { // Also considered that both x and y has no cell.
150	            locLowerBound = locUpperBound = NaN;
151	        }
152	
153	        if (eqNaN(locDimOut[0])) {
154	            locDimOut[0] = locLowerBound;
155	        }
156	        if (eqNaN(locDimOut[1])) {
157	            locDimOut[1] = locUpperBound;
158	        }
159	        locDimOut[0] = mathMax(mathMin(locDimOut[0], locUpperBound), locLowerBound);
160	        locDimOut[1] = mathMax(mathMin(locDimOut[1], locUpperBound), locLowerBound);
161	    }
162	}
163	
164	// The return val must be finite or NaN.
165	function parseCoordRangeOptionOnOneDimOnePart(
166	    locDimOut: MatrixXYLocatorRange[number],
167	    reasonOut: string[] | NullUndefined,
168	    coordValArr: MatrixCoordValueOption[],
169	    hasClamp: boolean,
170	    dims: MatrixDimPair,
171	    dimIdx: number,
172	    partIdx: number,
173	): void {
174	    const layout = coordDataToAllCellLevelLayout(coordValArr[partIdx], dims, dimIdx);
175	    if (!layout) {
176	        if (!hasClamp && reasonOut) {
177	            reasonOut.push(`Can not find layout by coord[${dimIdx}][${partIdx}].`);
178	        }
179	        locDimOut[0] = locDimOut[1] = NaN;
180	        return;
181	    }
182	    const locatorA = layout.id[XY[dimIdx]];
183	    let locatorB = locatorA;
184	    const dimCell = cellLayoutInfoToDimCell(layout);
185	    if (dimCell) { // Handle non-leaf
186	        locatorB += dimCell.span[XY[dimIdx]] - 1;
187	    }
188	    locDimOut[0] = mathMin(locDimOut[0], locatorA, locatorB);
189	    locDimOut[1] = mathMax(locDimOut[1], locatorA, locatorB);
190	}
191	
192	/**
193	 * @param locatorRange Must be the return of `parseCoordRangeOption`,
194	 *  where if not NaN, it must be a valid locator.
195	 */
196	export function isXYLocatorRangeInvalidOnDim(
197	    locatorRange: MatrixXYLocatorRange, dimIdx: number
198	): boolean {
199	    return eqNaN(locatorRange[dimIdx][0]) || eqNaN(locatorRange[dimIdx][1]);
200	}
201	
202	// `locatorRange` will be expanded (modified) if an intersection is encountered.
203	export function resolveXYLocatorRangeByCellMerge(
204	    inOutLocatorRange: MatrixXYLocatorRange,
205	    // Item indices coorespond to mergeDefList (len: mergeDefListTravelLen).
206	    // Indicating whether each item has be merged into the `locatorRange`
207	    outMergedMarkList: boolean[] | NullUndefined,
208	    mergeDefList: {
209	        locatorRange: MatrixXYLocatorRange | NullUndefined;
210	        cellMergeOwner: boolean;
211	    }[],
212	    mergeDefListTravelLen: number,
213	): void {
214	    outMergedMarkList = outMergedMarkList || _tmpOutMergedMarkList;
215	    for (let idx = 0; idx < mergeDefListTravelLen; idx++) {
216	        outMergedMarkList[idx] = false;
217	    }
218	    // In most case, cell merging definition list length is smaller than the range extent,
219	    // therefore, to detection intersection, travelling cell merging definition list is probably
220	    // performant than traveling the four edges of the rect formed by the locator range.
221	    while (true) {
222	        let expanded = false;
223	        for (let idx = 0; idx < mergeDefListTravelLen; idx++) {
224	            const mergeDef = mergeDefList[idx];
225	            if (!outMergedMarkList[idx]
226	                && mergeDef.cellMergeOwner
227	                && expandXYLocatorRangeIfIntersect(inOutLocatorRange, mergeDef.locatorRange)
228	            ) {
229	                outMergedMarkList[idx] = true;
230	                expanded = true;
231	            }
232	        }
233	        if (!expanded) {
234	            break;
235	        }
236	    }
237	}
238	const _tmpOutMergedMarkList: boolean[] = [];
239	
240	// Return whether intersect.
241	// `thisLocRange` will be expanded (modified) if an intersection is encountered.
242	function expandXYLocatorRangeIfIntersect(
243	    thisLocRange: MatrixXYLocatorRange,
244	    otherLocRange: MatrixXYLocatorRange
245	): boolean {
246	    if (!locatorRangeIntersectOneDim(thisLocRange[0], otherLocRange[0])
247	        || !locatorRangeIntersectOneDim(thisLocRange[1], otherLocRange[1])
248	    ) {
249	        return false;
250	    }
251	
252	    thisLocRange[0][0] = mathMin(thisLocRange[0][0], otherLocRange[0][0]);
253	    thisLocRange[0][1] = mathMax(thisLocRange[0][1], otherLocRange[0][1]);
254	    thisLocRange[1][0] = mathMin(thisLocRange[1][0], otherLocRange[1][0]);
255	    thisLocRange[1][1] = mathMax(thisLocRange[1][1], otherLocRange[1][1]);
256	
257	    return true;
258	}
259	
260	// Notice: If containing NaN, not intersect.
261	function locatorRangeIntersectOneDim(
262	    locRange1OneDim: MatrixXYLocatorRange[number],
263	    locRange2OneDim: MatrixXYLocatorRange[number],
264	): boolean {
265	    return (
266	        locRange1OneDim[1] >= locRange2OneDim[0]
267	        && locRange1OneDim[0] <= locRange2OneDim[1]
268	    );
269	}
270	
271	export function fillIdSpanFromLocatorRange(
272	    owner: {id: Point; span: Point;},
273	    locatorRange: MatrixXYLocatorRange
274	): void {
275	    owner.id.set(locatorRange[0][0], locatorRange[1][0]);
276	    owner.span.set(locatorRange[0][1] - owner.id.x + 1, locatorRange[1][1] - owner.id.y + 1);
277	}
278	
279	export function cloneXYLocatorRange(
280	    target: MatrixXYLocatorRange,
281	    source: MatrixXYLocatorRange
282	): void {
283	    target[0][0] = source[0][0];
284	    target[0][1] = source[0][1];
285	    target[1][0] = source[1][0];
286	    target[1][1] = source[1][1];
287	}
288	
289	/**
290	 * If illegal, the corresponding x/y/width/height is set to `NaN`.
291	 * `x/width` or `y/height` is supported to be calculated separately,
292	 * i.e., one side are NaN, the other side are normal.
293	 * @param oneDimOut only write to `x/width` or `y/height`, depending on `dimIdx`.
294	 */
295	export function xyLocatorRangeToRectOneDim(
296	    oneDimOut: RectLike,
297	    locRange: MatrixXYLocatorRange,
298	    dims: MatrixDimPair,
299	    dimIdx: number
300	) {
301	    const layoutMin = coordDataToAllCellLevelLayout(locRange[dimIdx][0], dims, dimIdx);
302	    const layoutMax = coordDataToAllCellLevelLayout(locRange[dimIdx][1], dims, dimIdx);
303	
304	    oneDimOut[XY[dimIdx]] = oneDimOut[WH[dimIdx]] = NaN;
305	
306	    if (layoutMin && layoutMax) {
307	        oneDimOut[XY[dimIdx]] = layoutMin.xy;
308	        oneDimOut[WH[dimIdx]] = layoutMax.xy + layoutMax.wh - layoutMin.xy;
309	    }
310	}
311	
