138	export interface MatrixBodyCornerCellOption extends MatrixBaseCellOption {
139	    // Text that can be displayed.
140	    value?: string;
141	    // Use it to reference a coord in matrix.
142	    coord?: MatrixCoordRangeOption[];
143	    // Merge cells determined by `coord`.
144	    mergeCells?: boolean;
