147	interface MatrixDimensionOption extends MatrixCellStyleOption, MatrixDimensionLevelOption {
148	    type?: 'category'; // For internal usage; force be 'category'.
149	    show?: boolean;
150	    data?: MatrixDimensionCellLooseOption[];
151	    // `levels[0]`: the topmost (for x dimension) or leftmost (for y dimension) level.
152	    // If not specified, use null/undefined, such as `levels: [null, null, {levelSize: 10}]`
153	    levels?: (MatrixDimensionLevelOption | NullUndefined)[];
154	    dividerLineStyle?: LineStyleOption;
155	}
156	
157	export interface MatrixDimensionCellOption extends MatrixBaseCellOption {
158	    // Use it to define a coord in matrix.
159	    // Do not use type `OrdinalRawValue` here. Number input is forbiden due to the possible confusion.
160	    // e.g., if `matrix.x.data: [1, 2, 3]` is allowed, then querying `coord: [1, null]` will actually get
161	    // the second column, since number represents the index (i.e. `MatrixXYLocator` or `OrdinalNumber`).
162	    value?: string;
