384	/**
385	 * The uniform entry of set text style, that is, retrieve style definitions
386	 * from `model` and set to `textStyle` object.
387	 *
388	 * Never in merge mode, but in overwrite mode, that is, all of the text style
389	 * properties will be set. (Consider the states of normal and emphasis and
390	 * default value can be adopted, merge would make the logic too complicated
391	 * to manage.)
392	 */
393	function setTextStyleCommon<
394	    TNuance extends TextCommonOptionNuanceBase = TextCommonOptionNuanceDefault
395	>(
396	    textStyle: TextStyleProps,
397	    textStyleModel: LabelCommonModel<TNuance>,
398	    opt?: Pick<
399	        TextCommonParams,
400	        'inheritColor' | 'defaultOpacity' | 'disableBox' | 'defaultTextMargin'
401	    >,
402	    isNotNormal?: boolean,
403	    isAttached?: boolean
404	) {
405	    // Consider there will be abnormal when merge hover style to normal style if given default value.
406	    opt = opt || EMPTY_OBJ;
407	    const ecModel = textStyleModel.ecModel;
408	    const globalTextStyle = ecModel && ecModel.option.textStyle;
409	    // Consider case:
410	    // {
411	    //     data: [{
412	    //         value: 12,
413	    //         label: {
414	    //             rich: {
415	    //                 // no 'a' here but using parent 'a'.
416	    //             }
417	    //         }
418	    //     }],
419	    //     rich: {
420	    //         a: { ... }
421	    //     }
422	    // }
423	    const richItemNames = getRichItemNames<TNuance>(textStyleModel);
424	    let richResult: TextStyleProps['rich'];
425	    if (richItemNames) {
426	        richResult = {};
427	        const richInheritPlainLabelOptionName = 'richInheritPlainLabel' as const;
428	        const richInheritPlainLabel: boolean = retrieve2(
429	            textStyleModel.get(richInheritPlainLabelOptionName as any),
430	            ecModel ? ecModel.get(richInheritPlainLabelOptionName) : undefined
431	        );
432	        for (const name in richItemNames) {
433	            if (richItemNames.hasOwnProperty(name)) {
434	                // Cascade is supported in rich.
435	                const richTextStyle = textStyleModel.getModel(['rich', name]) as LabelCommonModel<TNuance>;
436	                // In rich, never `disableBox`.
437	                // consider `label: {formatter: '{a|xx}', color: 'blue', rich: {a: {}}}`,
438	                // the default color `'blue'` will not be adopted if no color declared in `rich`.
439	                // That might confuses users. So probably we should put `textStyleModel` as the
440	                // root ancestor of the `richTextStyle`. But that would be a break change.
441	                // Since v6, the rich style inherits plain label by default
442	                // but this behavior can be disabled by setting `richInheritPlainLabel` to `false`.
443	                setTokenTextStyle<TNuance>(
444	                    richResult[name] = {}, richTextStyle, globalTextStyle, textStyleModel, richInheritPlainLabel,
445	                    opt, isNotNormal, isAttached, false, true
446	                );
447	            }
448	        }
449	    }
450	    if (richResult) {
451	        textStyle.rich = richResult;
452	    }
453	    const overflow = textStyleModel.get('overflow');
454	    if (overflow) {
455	        textStyle.overflow = overflow;
456	    }
457	    const minMargin = textStyleModel.get('minMargin');
458	    if (minMargin != null) {
459	        textStyle.margin = minMargin;
460	        (textStyle as LabelExtendedTextStyle).__marginType = LabelMarginType.minMargin;
461	    }
462	    const textMargin = textStyleModel.get('textMargin');
463	    if (textMargin != null) {
464	        textStyle.margin = clone(textMargin);
465	        (textStyle as LabelExtendedTextStyle).__marginType = LabelMarginType.textMargin;
466	    }
467	    else if (opt.defaultTextMargin != null) {
468	        textStyle.margin = clone(opt.defaultTextMargin);
469	        (textStyle as LabelExtendedTextStyle).__marginType = LabelMarginType.textMargin;
470	    }
471	    const lineOverflow = textStyleModel.get('lineOverflow');
472	    if (lineOverflow) {
473	        textStyle.lineOverflow = lineOverflow;
474	    }
475	    setTokenTextStyle<TNuance>(
476	        textStyle, textStyleModel, globalTextStyle, null, null, opt, isNotNormal, isAttached, true, false
477	    );
478	}
