73	/**
74	 * Lifetime: the same with `MatrixModel`, but different from `coord/Matrix`.
75	 */
76	export class MatrixBodyCorner<TKind extends MatrixBodyOrCornerKind> {
77	
78	    /**
79	     * Be sparse, item exists only if needed.
80	     */
81	    private _cellMap: MatrixModelBodyCornerCellMap | NullUndefined;
82	    private _cellMergeOwnerList: MatrixBodyCornerCell[];
83	
84	    private _model: Model<MatrixBodyOrCornerOption<TKind>>;
85	    private _dims: MatrixDimPair;
86	    private _kind: TKind;
87	
88	    constructor(
89	        kind: TKind,
90	        bodyOrCornerModel: Model<MatrixBodyOrCornerOption<TKind>>,
91	        dims: MatrixDimPair
92	    ) {
93	        this._model = bodyOrCornerModel;
94	        this._dims = dims;
95	        this._kind = kind;
96	        this._cellMergeOwnerList = [];
97	    }
98	
99	    /**
100	     * Can not be called before series models initialization finished, since the ordinalMeta may
101	     * use collect the values from `series.data` in series initialization.
102	     */
103	    private _ensureCellMap(): MatrixModelBodyCornerCellMap {
104	        const self = this;
105	
106	        let _cellMap = self._cellMap;
107	        if (!_cellMap) {
108	            _cellMap = self._cellMap = createHashMap();
109	            fillCellMap();
110	        }
111	        return _cellMap;
112	
113	        function fillCellMap(): void {
114	            type TmpParsed = {
115	                id: Point;
116	                span: Point;
117	                locatorRange: MatrixXYLocatorRange;
118	                option: MatrixBodyCornerCellOption;
119	                cellMergeOwner: boolean;
120	            };
121	            const parsedList: TmpParsed[] = [];
122	
123	            let cellOptionList = self._model.getShallow('data');
124	            if (cellOptionList && !isArray(cellOptionList)) {
125	                if (__DEV__) {
126	                    error(`matrix.${cellOptionList}.data must be an array if specified.`);
127	                }
128	                cellOptionList = null;
129	            }
130	            each(cellOptionList, (option, idx) => {
131	                if (!isObject(option) || !isArray(option.coord)) {
132	                    if (__DEV__) {
133	                        error(`Illegal matrix.${self._kind}.data[${idx}], must be a {coord: [...], ...}`);
134	                    }
135	                    return;
136	                }
137	
138	                const locatorRange = resetXYLocatorRange([]);
139	                let reasonArr: string[] | NullUndefined = null;
140	                if (__DEV__) {
141	                    reasonArr = [];
142	                }
143	                parseCoordRangeOption(
144	                    locatorRange, reasonArr, option.coord, self._dims, MatrixClampOption[self._kind]
145	                );
146	                if (isXYLocatorRangeInvalidOnDim(locatorRange, 0) || isXYLocatorRangeInvalidOnDim(locatorRange, 1)) {
147	                    if (__DEV__) {
148	                        error(`Can not determine cells by option matrix.${self._kind}.data[${idx}]: `
149	                            + `${reasonArr.join(' ')}`
150	                        );
151	                    }
152	                    return;
153	                }
154	
155	                const cellMergeOwner = option && option.mergeCells;
156	                const parsed: TmpParsed = {id: new Point(), span: new Point(), locatorRange, option, cellMergeOwner};
157	                fillIdSpanFromLocatorRange(parsed, locatorRange);
158	
159	                // The order of the `parsedList` determines the precedence of the styles, if there
160	                // are overlaps between ranges specified in different items. Preserve the original
161	                // order of `matrix.body/corner/data` to make it predictable for users.
162	                parsedList.push(parsed);
163	            });
164	
165	            // Resolve cell merging intersection - union to a larger rect.
166	            const mergedMarkList: boolean[] = [];
167	            for (let parsedIdx = 0; parsedIdx < parsedList.length; parsedIdx++) {
168	                const parsed = parsedList[parsedIdx];
169	                if (!parsed.cellMergeOwner) {
170	                    continue;
171	                }
172	                const locatorRange = parsed.locatorRange;
173	                resolveXYLocatorRangeByCellMerge(locatorRange, mergedMarkList, parsedList, parsedIdx);
174	                for (let idx = 0; idx < parsedIdx; idx++) {
175	                    if (mergedMarkList[idx]) {
176	                        parsedList[idx].cellMergeOwner = false;
177	                    }
178	                }
179	                if (locatorRange[0][0] !== parsed.id.x || locatorRange[1][0] !== parsed.id.y) {
180	                    // The top-left cell of the unioned locatorRange is not this cell any more.
181	                    parsed.cellMergeOwner = false;
182	                    // Reconcile: simply use the last style and value option if multiple styles involved
183	                    // in a merged area, since there might be no commonly used merge strategy.
184	                    const newOption = extend({} as MatrixBodyCornerCellOption, parsed.option);
185	                    newOption.coord = null;
186	                    const newParsed: TmpParsed = {
187	                        id: new Point(),
188	                        span: new Point(),
189	                        locatorRange,
190	                        option: newOption,
191	                        cellMergeOwner: true
192	                    };
193	                    fillIdSpanFromLocatorRange(newParsed, locatorRange);
194	                    parsedList.push(newParsed);
195	                }
196	            }
