198	            // Assign options to cells.
199	            each(parsedList, parsed => {
200	                const topLeftCell = ensureBodyOrCornerCell(parsed.id.x, parsed.id.y);
201	                if (parsed.cellMergeOwner) {
202	                    topLeftCell.cellMergeOwner = true;
203	                    topLeftCell.span = parsed.span;
204	                    topLeftCell.locatorRange = parsed.locatorRange;
205	                    topLeftCell.spanRect = createNaNRectLike();
206	                    self._cellMergeOwnerList.push(topLeftCell);
207	                }
208	                if (!parsed.cellMergeOwner && !parsed.option) {
209	                    return;
210	                }
211	                for (let yidx = 0; yidx < parsed.span.y; yidx++) {
212	                    for (let xidx = 0; xidx < parsed.span.x; xidx++) {
213	                        const cell = ensureBodyOrCornerCell(parsed.id.x + xidx, parsed.id.y + yidx);
214	                        // If multiple style options are defined on a cell, the later ones takes precedence.
215	                        cell.option = parsed.option;
216	                        if (parsed.cellMergeOwner) {
217	                            cell.inSpanOf = topLeftCell;
218	                        }
219	                    }
220	                }
221	            });
222	        } // End of fillCellMap
223	
224	        function ensureBodyOrCornerCell(x: MatrixXYLocator, y: MatrixXYLocator): MatrixBodyCornerCell {
225	            const key = makeCellMapKey(x, y);
226	            let cell = _cellMap.get(key);
227	            if (!cell) {
228	                cell = _cellMap.set(key, {
229	                    id: new Point(x, y),
230	                    option: null,
231	                    inSpanOf: null,
232	                    span: null,
233	                    spanRect: null,
234	                    locatorRange: null,
235	                    cellMergeOwner: false,
236	                });
237	            }
238	            return cell;
239	        }
240	    }
241	
242	    /**
243	     * Body cells or corner cell are not commonly defined specifically, especially in a large
244	     * table, thus his is a sparse data structure - bodys or corner cells exist only if there
245	     * are options specified to it (in `matrix.body.data` or `matrix.corner.data`);
246	     * otherwise, return `NullUndefined`.
247	     */
248	    getCell(xy: MatrixXYLocator[]): MatrixBodyCornerCell | NullUndefined {
249	        // Assert xy do not contain NaN
250	        return this._ensureCellMap().get(makeCellMapKey(xy[0], xy[1]));
251	    }
252	
253	    /**
254	     * Only cell existing (has specific definition or props) will be travelled.
255	     */
256	    travelExistingCells(cb: (cell: MatrixBodyCornerCell) => void): void {
257	        this._ensureCellMap().each(cb);
258	    }
259	
260	    /**
261	     * @param locatorRange Must be the return of `parseCoordRangeOption`.
262	     */
263	    expandRangeByCellMerge(locatorRange: MatrixXYLocatorRange): void {
264	        if (
265	            isXYLocatorRangeInvalidOnDim(locatorRange, 0)
266	            && isXYLocatorRangeInvalidOnDim(locatorRange, 1)
267	            && locatorRange[0][0] === locatorRange[0][1]
268	            && locatorRange[1][0] === locatorRange[1][1]
269	        ) {
270	            // If it locates to a single cell, use this quick path to avoid travelling.
271	            // It is based on the fact that any cell is not contained by more than one cell merging rect.
272	            _tmpERBCMLocator[0] = locatorRange[0][0];
273	            _tmpERBCMLocator[1] = locatorRange[1][0];
274	            const cell = this.getCell(_tmpERBCMLocator);
275	            const inSpanOf = cell.inSpanOf;
276	            if (inSpanOf) {
277	                cloneXYLocatorRange(locatorRange, inSpanOf.locatorRange);
278	                return;
279	            }
280	        }
281	
282	        const list = this._cellMergeOwnerList;
283	        resolveXYLocatorRangeByCellMerge(locatorRange, null, list, list.length);
284	    }
285	
286	}
287	const _tmpERBCMLocator: MatrixXYLocator[] = [];
288	
289	function makeCellMapKey(x: MatrixXYLocator, y: MatrixXYLocator): string {
290	    return `${x}|${y}`;
291	}
