48	class Model<Opt = ModelOption> {    // TODO: TYPE use unknown instead of any?
49	
50	    // [Caution]: Because this class or desecendants can be used as `XXX.extend(subProto)`,
51	    // the class members must not be initialized in constructor or declaration place.
52	    // Otherwise there is bad case:
53	    //   class A {xxx = 1;}
