58	    //   console.log(c.xxx); // expect 5 but always 1.
59	
60	    parentModel: Model;
61	
62	    ecModel: GlobalModel;
63	
64	    option: Opt;    // TODO Opt should only be object.
65	
66	    constructor(option?: Opt, parentModel?: Model, ecModel?: GlobalModel) {
67	        this.parentModel = parentModel;
68	        this.ecModel = ecModel;
69	        this.option = option;
