82	    init(option: Opt, parentModel?: Model, ecModel?: GlobalModel, ...rest: any): void {}
83	
84	    /**
85	     * Merge the input option to me.
86	     */
87	    mergeOption(option: Opt, ecModel?: GlobalModel): void {
