89	    }
90	
91	    // FIXME:TS consider there is parentModel,
92	    // return type have to be ModelOption or can be Option<R>?
93	    // (Is there any chance that parentModel value type is different?)
94	    get<R extends keyof Opt>(
95	        path: R, ignoreParent?: boolean
96	    ): Opt[R];
97	    get<R extends keyof Opt>(
98	        path: readonly [R], ignoreParent?: boolean
99	    ): Opt[R];
100	    get<R extends keyof Opt, S extends keyof Opt[R]>(
101	        path: readonly [R, S], ignoreParent?: boolean
102	    ): Opt[R][S];
103	    get<R extends keyof Opt, S extends keyof Opt[R], T extends keyof Opt[R][S]>(
104	        path: readonly [R, S, T], ignoreParent?: boolean
105	    ): Opt[R][S][T];
106	    // `path` can be 'a.b.c', so the return value type have to be `ModelOption`
107	    // TODO: TYPE strict key check?
