148	    ): Model<Opt[Ra]> | Model<Opt[Rb][S]>;
149	    getModel<R extends keyof Opt, S extends keyof Opt[R], T extends keyof Opt[R][S]>(
150	        path: readonly [R, S, T], parentModel?: Model
151	    ): Model<Opt[R][S][T]>;
152	    // `path` can be 'a.b.c', so the return value type have to be `Model<ModelOption>`
153	    // getModel(path: string | string[], parentModel?: Model): Model;
154	    // TODO 'a.b.c' is deprecated
155	    getModel(path: string | readonly string[], parentModel?: Model): Model<any> {
156	        const hasPath = path != null;
157	        const pathFinal = hasPath ? this.parsePath(path) : null;
158	        const obj = hasPath
159	            ? this._doGet(pathFinal)
160	            : this.option;
161	
162	        parentModel = parentModel || (
163	            this.parentModel
164	                && this.parentModel.getModel(this.resolveParentPath(pathFinal) as [string])
165	        );
166	
167	        return new Model(obj, parentModel, this.ecModel);
168	    }
169	
170	    /**
171	     * If model has option
172	     */
173	    isEmpty(): boolean {
174	        return this.option == null;
175	    }
176	
177	    restoreData(): void {}
178	
179	    // Pending
180	    clone(): Model<Opt> {
181	        const Ctor = this.constructor;
182	        return new (Ctor as any)(clone(this.option));
183	    }
184	
185	    // setReadOnly(properties): void {
186	        // clazzUtil.setReadOnly(this, properties);
187	    // }
188	
189	    // If path is null/undefined, return null/undefined.
190	    parsePath(path: string | readonly string[]): readonly string[] {
191	        if (typeof path === 'string') {
192	            return path.split('.');
193	        }
194	        return path;
195	    }
196	
197	    // Resolve path for parent. Perhaps useful when parent use a different property.
198	    // Default to be a identity resolver.
199	    // Can be modified to a different resolver.
200	    resolveParentPath(path: readonly string[]): string[] {
201	        return path as string[];
202	    }
203	
204	    // FIXME:TS check whether put this method here
205	    isAnimationEnabled(): boolean {
206	        if (!env.node && this.option) {
207	            if ((this.option as AnimationOptionMixin).animation != null) {
208	                return !!(this.option as AnimationOptionMixin).animation;
209	            }
210	            else if (this.parentModel) {
211	                return this.parentModel.isAnimationEnabled();
212	            }
213	        }
214	    }
215	
216	    private _doGet(pathArr: readonly string[], parentModel?: Model<Dictionary<any>>) {
217	        let obj = this.option;
218	        if (!pathArr) {
219	            return obj;
220	        }
221	
222	        for (let i = 0; i < pathArr.length; i++) {
223	            // Ignore empty
224	            if (!pathArr[i]) {
225	                continue;
226	            }
227	            // obj could be number/string/... (like 0)
228	            obj = (obj && typeof obj === 'object')
229	                ? (obj as ModelOption)[pathArr[i] as keyof ModelOption] : null;
230	            if (obj == null) {
231	                break;
232	            }
233	        }
234	        if (obj == null && parentModel) {
235	            obj = parentModel._doGet(
236	                this.resolveParentPath(pathArr) as [string],
237	                parentModel.parentModel
238	            ) as any;
239	        }
240	
241	        return obj;
242	    }
243	};
